class Solution {
 public:
  int divide(int dividend, int divisor) {
    // -2^{31} / -1 = 2^31 will overflow, so return 2^31 - 1.
    if (dividend == INT_MIN && divisor == -1)
      return INT_MAX;

    const int sign = dividend > 0 ^ divisor > 0 ? -1 : 1;
    long long ans = 0;
    long long dvd = dividend;
    long long dvs = divisor;
    if (dvd < 0) dvd = -dvd;
    if (dvs < 0) dvs = -dvs;

    while (dvd >= dvs) {
      long long k = 1;
      long long chunk = dvs;
      while ((chunk << 1) <= dvd) {
        chunk <<= 1;
        k <<= 1;
      }
      dvd -= chunk;
      ans += k;
    }

    return sign < 0 ? -ans : ans;
  }
};

